	// EXPECT-1: cache_warmup_e2e_ms < 4200
	// RESULT-1: REFUTED (actual=4256.8874134)

	// HYPOTHESIS-2: Separating queue depth from batch size in penalty calculation avoids penalizing instances that are actively processing (high batch) but have low queue depth
	// MECHANISM-2: QueueDepth indicates waiting requests (bad), while BatchSize indicates active processing (neutral); penalizing only queue buildup routes to instances that will finish soon
	// EXPECT-2: combined_score > -3800

	// HYPOTHESIS-3: Input-length-aware cache bonus means large requests get routed to cache-warm instances more aggressively since they benefit most from prefix cache hits
	// MECHANISM-3: Large inputs have higher recomputation cost; stronger cache affinity for them reduces total compute time while small requests can absorb cache misses cheaply
	// EXPECT-3: avg_e2e_ms < 2500
	// RESULT-3: REFUTED (actual=2550.9638108444447)

	// Compute composite scores from all scorers
	scores := make(map[string]float64, len(snapshots))
	for i, scorer := range ws.scorers {
		dimScores := scorer(req, snapshots)
		for _, snap := range snapshots {
			s := dimScores[snap.ID]
			if s < 0 {
				s = 0
			}
			if s > 1 {
				s = 1
			}
			scores[snap.ID] += s * ws.weights[i]
		}
	}

	// Find min queue depth and min effective load
	minQD := snapshots[0].QueueDepth + snapshots[0].PendingRequests
	minLoad := snapshots[0].EffectiveLoad()
	for _, snap := range snapshots[1:] {
		qd := snap.QueueDepth + snap.PendingRequests
		if qd < minQD {
			minQD = qd
		}
		el := snap.EffectiveLoad()
		if el < minLoad {
			minLoad = el
		}
	}

	inputLen := len(req.InputTokens)
	isSession := req.SessionID != ""

	// Adaptive post-scoring adjustments
	for _, snap := range snapshots {
		qd := snap.QueueDepth + snap.PendingRequests
		el := snap.EffectiveLoad()

		// Queue-aware load penalty: penalize queue buildup (waiting) more than batch (processing)
		qdDiff := float64(qd - minQD)
		loadDiff := float64(el - minLoad)
		if qdDiff > 0 {
			// Moderate penalty on queue difference - allows cache affinity to win for small diffs
			penalty := 1.0 / (1.0 + 0.3*qdDiff*qdDiff)
			scores[snap.ID] *= penalty
		} else if loadDiff > 3 {
			// Only penalize pure batch-load if very high
			scores[snap.ID] *= 0.8
		}

