		if inputLen > 256 {
			// Large inputs: strong cache preference
			scores[snap.ID] += 0.35 * snap.CacheHitRate
		} else if inputLen > 64 {
			// Medium inputs: moderate cache preference
			scores[snap.ID] += 0.2 * snap.CacheHitRate
		} else {
			// Small inputs: mild cache preference
			scores[snap.ID] += 0.1 * snap.CacheHitRate
		}

