		if isSession {
			scores[snap.ID] += 0.4 * snap.CacheHitRate
		}

		// KV memory pressure: hard cutoff only at extreme pressure
		if snap.KVUtilization > 0.9 {
			scores[snap.ID] *= 0.2
		} else if snap.KVUtilization > 0.8 {
			scores[snap.ID] *= 0.6
		}

		// Free blocks bonus: prefer instances with more headroom (diminishing returns)
		if snap.FreeKVBlocks > 0 {
			freeRatio := float64(snap.FreeKVBlocks) / (float64(snap.FreeKVBlocks) + 50.0)
			scores[snap.ID] += freeRatio * 0.1
		}

		// Ensure score doesn't collapse
		if scores[snap.ID] < 0.001 {
			scores[snap.ID] = 0.001
		}
	}

	// Argmax: select instance with highest composite score.
	bestScore := -1.0
	bestIdx := 0
	for i, snap := range snapshots {
		if scores[snap.ID] > bestScore {
			bestScore = scores[snap.ID]
			bestIdx = i
		}
	}
